boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    String strToCheck = str;
    String suffixToCheck = suffix;
    if (ignoreCase) {
        strToCheck = strToCheck.toLowerCase();
        suffixToCheck = suffixToCheck.toLowerCase();
    }
    return strToCheck.endsWith(suffixToCheck);
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    if (ignoreCase) {
        return str.equalsIgnoreCase(suffix);
    } else {
        return str.endsWith(suffix);
    }
}

